template<unsigned Bits> inline std::uint32_t graphicalPacked(std::size_t offset, std::size_t index) {
    constexpr auto perWord = 32 / Bits;
    return (graphicalData[offset + index / perWord] >> ((index % perWord) * Bits)) & ((1u << Bits) - 1u);
}
inline bool isGraphical(std::uint32_t scalar) {
    const auto first = scalar >> 13;
    const auto second = (graphicalPacked<8>(0, first) << 5) | ((scalar >> 8) & 31u);
    const auto bit = (graphicalPacked<16>(64, second) << 8) | (scalar & 255u);
    return graphicalPacked<1>(416, bit) != 0;
}
